public void init()
{
    next init();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        this.design().controlName(formControlStr(RetailPricingSimulator, PricingSimulatorPriceGroups_PriceGroups)).visible(false);
        this.design().controlName(formControlStr(RetailPricingSimulator, RetailPricingSimulatorPriceDiscTable_AccountCode)).visible(false);
        this.design().controlName(formControlStr(RetailPricingSimulator, RetailPricingSimulatorPriceDiscTable_AccountRelation)).visible(false);
        this.design().controlName(formControlStr(RetailPricingSimulator, RetailPricingSimulatorPriceDiscTable_ItemCode)).visible(false);
        this.design().controlName(formControlStr(RetailPricingSimulator, RetailPricingSimulatorPriceDiscTable_ItemRelation)).visible(false);

        //Enable new controls;
        RetailPricingSimulatorPriceDiscTable_Selected.visible(true);
        RetailPricingSimulatorPriceDiscTable_PriceComponentCombination.visible(true);
        RetailPricingSimulatorPriceDiscTable_PricingAttributeGroupNameHeader.visible(true);
        RetailPricingSimulatorPriceDiscTable_PricingAttributeDetailsHeader.visible(true);
        RetailPricingSimulatorPriceDiscTable_PricingAttributeGroupNameLine.visible(true);
        RetailPricingSimulatorPriceDiscTable_PricingAttributeDetailsLine.visible(true);
        RetailPricingSimulatorPriceDiscTable_PriceApplyAdjustment.visible(true);
        RetailPricingSimulatorPriceDiscTable_UnitAppliesToAll.visible(true);
        RetailPricingSimulatorPriceDiscTable_JournalNum.visible(true);
        RetailPricingSimulatorPriceDiscTable_PriceComponentPriority.visible(true);
    }
}

[FormDataSourceEventHandler(formDataSourceStr(RetailPricingSimulator, RetailPricingSimulatorPriceDiscTable), FormDataSourceEventType::QueryExecuting)]
public static void RetailPricingSimulatorPriceDiscTable_OnQueryExecuting(FormDataSource sender, FormDataSourceEventArgs e)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        //This would make sure the extension field is also fetched.
        QueryBuildDataSource qbds = sender.queryBuildDataSource();
        qbds.addAllFields(tableStr(RetailPricingSimulatorPriceDiscTable));
    }
}
